const CACHE='pilot-prep-2026.10.14.1';
const FILES=["./","./index.html","./styles.css","./polish.css","./app.mjs","./engine.mjs","./storage.mjs","./charts.mjs","./e6b.mjs","./e6b-ui.mjs","./e6b.css","./manifest.webmanifest","./apple-touch-icon.png","./apple-touch-icon-precomposed.png","./app-icon-180.png","./app-icon-192.png","./app-icon-512.png","./app-icon-maskable-512.png","./favicon.png","./favicon.ico","./data/bank-a.json","./data/bank-b.json","./data/figures-a.json","./data/figures-b.json","./assets/cloud-180-v8.png","./assets/cloud-192-v8.png","./assets/cloud-512-v8.png","./assets/cloud-v8.svg","./assets/figure-1.png","./assets/figure-12.png","./assets/figure-14.png","./assets/figure-15.png","./assets/figure-17.png","./assets/figure-19.png","./assets/figure-2.png","./assets/figure-20.png","./assets/figure-21.png","./assets/figure-22.png","./assets/figure-23.png","./assets/figure-26.png","./assets/figure-27.png","./assets/figure-28.png","./assets/figure-3.png","./assets/figure-31.png","./assets/figure-32.png","./assets/figure-33.png","./assets/figure-34.png","./assets/figure-35.png","./assets/figure-36.png","./assets/figure-37.png","./assets/figure-38.png","./assets/figure-4.png","./assets/figure-40.png","./assets/figure-47.png","./assets/figure-48.png","./assets/figure-49.png","./assets/figure-5.png","./assets/figure-50.png","./assets/figure-52.png","./assets/figure-58.png","./assets/figure-59.png","./assets/figure-6.png","./assets/figure-64.png","./assets/figure-65.png","./assets/figure-7.png","./assets/figure-8.png","./assets/figure-9.png","./assets/icon-180.png","./assets/icon-192.png","./assets/icon-512.png","./assets/icon.svg"];
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);await c.addAll(FILES);await c.put('./offline-ready',new Response('ready'));const clientsList=await self.clients.matchAll({includeUncontrolled:true});clientsList.forEach(c=>c.postMessage('offline-ready'));})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('pilot-prep-')&&k!==CACHE).map(k=>caches.delete(k)));await self.clients.claim();})()));
self.addEventListener('message',e=>{if(e.data==='activate-update')self.skipWaiting();});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.pathname==='/sw.js'||/signin|signout|callback/.test(u.pathname))return;const known=FILES.some(f=>new URL(f,self.registration.scope).pathname===u.pathname);if(!known&&e.request.mode!=='navigate')return;e.respondWith((async()=>{const c=await caches.open(CACHE);if(e.request.mode==='navigate'){try{const r=await fetch(e.request);if(r.ok&&!r.redirected){await c.put('./',r.clone());return r;}const offline=await c.match('./');return offline||r;}catch{return await c.match('./');}}return await c.match(e.request)||fetch(e.request);})());});
